from collections import Counter
import re

class NLPDataProcessor2:
    MAX_WORD_FREQUENCY_COUNT = 5
    NON_ENGLISH_PATTERN = r'[^a-zA-Z\s]'

    def process_data(self, string_list):
        return [self._process_string_to_words(string) for string in string_list]

    def _process_string_to_words(self, string):
        cleaned_string = re.sub(self.NON_ENGLISH_PATTERN, '', string.lower())
        return cleaned_string.split()

    def calculate_word_frequency(self, words_list):
        word_frequency_counter = self._build_word_frequency_counter(words_list)
        sorted_word_frequency = self._sort_word_frequency(word_frequency_counter)
        return self._extract_top_word_frequency(sorted_word_frequency, self.MAX_WORD_FREQUENCY_COUNT)

    def _build_word_frequency_counter(self, words_list):
        word_frequency = Counter()
        for words in words_list:
            word_frequency.update(words)
        return word_frequency

    def _sort_word_frequency(self, word_frequency):
        return dict(sorted(word_frequency.items(), key=lambda x: x[1], reverse=True))

    def _extract_top_word_frequency(self, sorted_word_frequency, count):
        return dict(list(sorted_word_frequency.items())[:count])

    def process(self, string_list):
        words_list = self.process_data(string_list)
        return self.calculate_word_frequency(words_list)
